class Solution {
    public List<String> removeSubfolders(String[] folder){
        Arrays.sort(folder);
        List<String> answer=new ArrayList<>();
        for(String path:folder)if(answer.isEmpty()||!path.startsWith(answer.get(answer.size()-1)+"/"))answer.add(path);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun removeSubfolders(folder:Array<String>):List<String>{
        folder.sort();
        val answer=mutableListOf<String>();
        for(path in folder)if(answer.isEmpty()||!path.startsWith(answer.last()+"/"))answer.add(path);
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<string> removeSubfolders(vector<string>& folder){
        sort(folder.begin(),folder.end());
        vector<string> answer;
        for(string& path:folder)if(answer.empty()||path.rfind(answer.back()+"/",0)!=0)answer.push_back(path);
        return answer;
    }
};
